  /* ===== Từ đặc biệt nhiều nghĩa ===== */
  const RECORD_ENTRY = {
  word:'record', tags:['học thuật','công nghệ'],
  synonyms:['document','disc'], antonyms:[],
  senses:[
    { pronunciation:'/ˈrekɔːd/', partOfSpeech:'noun', definitionEN:'A piece of evidence or information kept for future reference.', definitionVI:'Hồ sơ, bản ghi.', examples:['Keep a record of all your expenses.'] },
    { pronunciation:'/rɪˈkɔːd/', partOfSpeech:'verb', definitionEN:'To set down in writing or capture in permanent form.', definitionVI:'Ghi lại, thu âm.', examples:['They recorded the meeting for people who could not attend.'] }
  ]
};

  /* Bộ từ tiếng Trung (ZH_WORDS — khóa học riêng) nằm ở cuối file. */

  /** Chuyển 1 dòng nén → entry chuẩn (senses dùng meaning map) */
  function toEntry(row) {
    const [word, ipa, pos, defEN, defVI, example, tag, syn, ant, root, ...extras] = row;
    const meaning = { en: defEN, vi: defVI };
    const senses = [{
      pronunciation: ipa,
      partOfSpeech: pos,
      meaning,
      examples: [example],
    }].concat((extras || []).map((x) => ({
      pronunciation: (x && x.i) || ipa || '',
      partOfSpeech: (x && x.p) || '',
      meaning: { en: (x && x.e) || '', vi: (x && x.v) || '' },
      examples: (x && x.x) ? [x.x] : [],
      synonyms: (x && x.s) || [],
      antonyms: (x && x.a) || [],
    })));
    return {
      id: VA.uid(),
      word,
      tags: [tag],
      dateAdded: new Date().toISOString(),
      learningStatus: 'new',
      correctStreak: 0,
      synonyms: syn || [],
      antonyms: ant || [],
      wordRoot: root || '',
      senses,
    };
  }

  /** Mở cho module bài học dùng (chuyển dòng nén → entry) */
  VA.toEntry = toEntry;

  /** Tạo entry "record" đặc biệt (2 nghĩa, phát âm khác nhau) */
  function buildRecordEntry() {
    const e = JSON.parse(JSON.stringify(RECORD_ENTRY));
    e.id = VA.uid();
    e.dateAdded = new Date().toISOString();
    e.learningStatus = 'new';
    e.correctStreak = 0;
    e.tags = e.tags || ['học thuật', 'công nghệ'];
    e.senses = (e.senses || []).map((s) => ({
      pronunciation: s.pronunciation || '',
      partOfSpeech: s.partOfSpeech || '',
      meaning: { en: s.definitionEN || '', vi: s.definitionVI || '' },
      examples: s.examples || [],
    }));
    return e;
  }

  /** Tạo bộ từ vựng ban đầu (khi kho trống hoàn toàn) */
  VA.buildSeedEntries = function () {
    return SEED_WORDS.map(toEntry).concat([buildRecordEntry()]);
  };

  /**
   * Merge các từ seed còn thiếu vào kho hiện tại (không ghi đè, không trùng).
   * @returns số từ đã thêm
   */
  VA.mergeSeeds = function (entries) {
    const existing = new Set(entries.map((e) => e.word.toLowerCase()));
    let added = 0;
    SEED_WORDS.forEach((row) => {
      if (existing.has(row[0].toLowerCase())) return;
      entries.push(toEntry(row));
      existing.add(row[0].toLowerCase());
      added++;
    });
    if (!existing.has('record')) {
      entries.push(buildRecordEntry());
      added++;
    }
    return added;
  };

  /** Phiên bản dữ liệu seed — tăng lên khi kho từ có thay đổi cấu trúc/nội dung
   *  (main.js so sánh settings.seedVersion để chạy applySeedUpgrade 1 lần). */
  VA.SEED_VERSION = 2;

  /**
   * Nâng cấp entry đã có trong kho: THÊM các nghĩa bổ sung (đa nghĩa) mới từ seed
   * vào entry hiện hữu — giữ nguyên mọi thứ người dùng đã sửa (học trạng thái,
   * ngày thêm, sense đã có…), chỉ thêm sense có LOẠI TỪ chưa tồn tại.
   * @returns số entry được nâng cấp
   */
  VA.applySeedUpgrade = function (entries) {
    const byWord = new Map(entries.map((e) => [e.word.toLowerCase(), e]));
    let updated = 0;
    SEED_WORDS.forEach((row) => {
      const e = byWord.get(row[0].toLowerCase());
      if (!e || !Array.isArray(e.senses)) return;
      const fresh = toEntry(row);
      const havePos = new Set(e.senses.map((s) => s.partOfSpeech).filter(Boolean));
      let changed = false;
      fresh.senses.forEach((fs) => {
        if (havePos.has(fs.partOfSpeech)) return; // đã có loại từ này rồi
        e.senses.push(fs);
        havePos.add(fs.partOfSpeech);
        changed = true;
      });
      if ((!e.synonyms || !e.synonyms.length) && fresh.synonyms.length) e.synonyms = fresh.synonyms;
      if ((!e.antonyms || !e.antonyms.length) && fresh.antonyms.length) e.antonyms = fresh.antonyms;
      if (!e.wordRoot && fresh.wordRoot) e.wordRoot = fresh.wordRoot;
      if (changed) updated++;
    });
    return updated;
  };

